<script setup lang="ts">
import { ref,computed } from 'vue'
import { useRoute } from 'vue-router'
import { useProtocol } from '../stores/protocol'
import { usePlatform } from '../stores/platform'
import type { MarkRecord } from '../domain/types'
import PageHead from '../components/PageHead.vue'
import Icon from '../components/Icon.vue'
import Badge from '../components/Badge.vue'
import Modal from '../components/Modal.vue'
import Empty from '../components/Empty.vue'
const arbitrationDetails=ref<number[]>([])
const p=useProtocol(),s=usePlatform(),route=useRoute(),page=computed(()=>String(route.params.page));const active=ref<MarkRecord|null>(null),reviewer=ref(s.person.reviewer||''),scores=ref<number[]>([]),signature=ref(''),note=ref(''),arbitrationScore=ref(22),search=ref(''),skillId=ref(String(s.visibleSkills.find(k=>k.id===route.query.task)?.id||s.visibleSkills[0]?.id||'')),skillScores=ref<number[]>([]),skillSignature=ref(''),skillNote=ref('')
const titles:Record<string,[string,string]>={tasks:['阅卷任务','按评分标准独立评阅，双评结果汇总后进入核定或仲裁。'],arbitration:['差值与仲裁','对超出评分差值阈值的答卷进行复核，记录最终定分依据。'],skill:['现场技能评分','依据准备要求与评分表，完成现场考评与操作留痕。'],progress:['评分进度','查看评分任务状态与专家提交情况，掌握评阅进度。'],history:['历史评分','查询已核定、已发布的评分记录及仲裁意见。']}
const title=computed(()=>titles[page.value]||titles.tasks!)
const filtered=computed(()=>s.visibleMarks.filter(m=>page.value==='arbitration'?m.status==='待仲裁':page.value==='history'?['已核定','已发布'].includes(m.status):['待阅卷','待另一评'].includes(m.status)&&m.scores[s.person.reviewer||'']===undefined).filter(m=>!search.value||m.anonymous.includes(search.value)||m.title.includes(search.value)))
function open(m:MarkRecord){arbitrationDetails.value=m.rubric.map(()=>0);active.value=m;scores.value=m.rubric.map(()=>0);signature.value='';note.value='';reviewer.value=s.person.reviewer||'';arbitrationScore.value=m.final||Math.round(Object.values(m.scores).reduce((a,b)=>a+b,0)/Math.max(1,Object.values(m.scores).length))}
function submit(){s.run(()=>{s.markPaper(active.value!.id,reviewer.value,scores.value,signature.value);active.value=null})}
function arbitrate(){s.run(()=>{s.arbitrate(active.value!.id,active.value!.questionIds?.length?arbitrationDetails.value.reduce((a,b)=>a+b,0):arbitrationScore.value,note.value,signature.value,active.value!.questionIds?.length?arbitrationDetails.value:undefined);active.value=null})}
const skill=computed(()=>s.visibleSkills.find(k=>k.id===skillId.value)!);const skillQuestion=computed(()=>skill.value.questionSnapshot||s.data.questions.find(q=>q.id===skill.value.questionId)!)
function loadSkill(){if(!skill.value)return;skillScores.value=[...skill.value.scores];skillSignature.value=skill.value.signature;skillNote.value=skill.value.note}loadSkill()
function saveSkill(){s.run(()=>s.saveSkill(skill.value.id,skillScores.value,skillSignature.value,skillNote.value))}
const done=computed(()=>s.visibleMarks.filter(m=>['已核定','已发布'].includes(m.status)).length)
</script>
<template><PageHead :title="title[0]" :subtitle="title[1]" eyebrow="阅卷评分 / 评价工作区"><span class="security-pill"><Icon name="ShieldCheck" :size="16"/>{{page==='skill'?'现场评分 · 合成任务':'阅卷评分 · 合成答卷'}}</span></PageHead>
<template v-if="page==='tasks'||page==='arbitration'||page==='history'"><div v-if="page==='arbitration'" class="notice warning"><Icon name="Scale" :size="19"/>当前演示阈值：评分差值大于{{s.data.settings.threshold}}分触发仲裁。差值等于阈值时按配置规则核分。</div><div class="mini-metrics"><div><span>答卷总数</span><strong>{{s.visibleMarks.length}} <small>份</small></strong></div><div><span>已核定</span><strong>{{done}} <small>份</small></strong></div><div><span>待仲裁</span><strong>{{s.visibleMarks.filter(m=>m.status==='待仲裁').length}} <small>份</small></strong></div><div><span>整体进度</span><strong>{{Math.round(done/Math.max(1,s.visibleMarks.length)*100)}} <small>%</small></strong></div></div><section class="panel"><div class="filter-bar"><div class="input-icon"><Icon name="Search" :size="17"/><input v-model="search" placeholder="搜索匿名答卷号、试题名称…"/></div><span class="filter-meta">{{page==='history'?'已锁定评分记录':'仅显示分配给当前人员的任务'}}</span></div><div class="table-scroll"><table><thead><tr><th>匿名答卷</th><th>评阅内容</th><th>评分模式</th><th>专家评分</th><th>差值</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="m in filtered"><td><strong>{{m.anonymous}}</strong><small>{{m.attemptId.startsWith('HIST')?'预置历史合成卷':'实际演示答卷'}}</small></td><td>{{m.title}}<small>主观题满分 {{m.max}} 分</small></td><td>{{m.rule||s.data.settings.scoreRule}}<small>阈值 {{m.threshold??s.data.settings.threshold}} 分</small></td><td>{{['待阅卷','待另一评'].includes(m.status)?'独立评阅中':Object.values(m.scores).join(' / ')||'尚未提交'}}<small>{{Object.keys(m.scores).length}}人已评</small></td><td><strong :class="{'text-red':m.status==='待仲裁'}">{{Object.values(m.scores).length>1?Math.max(...Object.values(m.scores))-Math.min(...Object.values(m.scores)):'—'}}</strong></td><td><Badge :text="m.status"/></td><td><button class="text-button" @click="open(m)">{{m.status==='待仲裁'?'开始仲裁':['已核定','已发布'].includes(m.status)?'查看记录':'开始阅卷'}}<Icon name="ArrowRight" :size="14"/></button></td></tr></tbody></table></div><Empty v-if="!filtered.length"/></section></template>
<template v-if="page==='skill'&&skill"><div class="filter-bar panel"><label class="inline-label">考评任务<select v-model="skillId" @change="loadSkill"><option v-for="k in s.visibleSkills" :value="k.id">{{k.candidate}} · {{k.status}}</option></select></label><Badge :text="skill.status"/><span class="filter-meta">桌面 / 平板 / 手机窄屏评分布局</span></div><div class="skill-layout"><section class="panel"><div class="panel-head"><h3>{{skillQuestion.title}}</h3><Badge text="技能考核"/></div><div class="skill-brief"><h4><Icon name="UserRoundCheck" :size="18"/>考生准备</h4><p>{{skillQuestion.preparation}}</p><h4><Icon name="Wrench" :size="18"/>考场准备</h4><p>{{skillQuestion.venue}}</p><h4><Icon name="ClipboardList" :size="18"/>考核要求</h4><p>{{skillQuestion.analysis}}</p><div class="notice">场次：{{skill.batch||'技能认定模拟场'}} · {{skill.venue||'工位 A01'}}<br/>考生：{{skill.candidate}} · 考评员：{{skill.assessor||s.actor}}</div></div></section><section class="panel skill-score"><div class="panel-head"><h3>现场评分表</h3><strong class="text-blue">{{skillScores.reduce((a,b)=>a+Number(b),0)}} / 100分</strong></div><div v-for="(r,i) in skillQuestion.rubric" class="skill-item"><span class="step-num">0{{i+1}}</span><div><strong>{{r.label}}</strong><small>满分 {{r.max}} 分</small></div><input v-model.number="skillScores[i]" type="number" :min="0" :max="r.max" :disabled="skill.status==='已提交'" :aria-label="r.label+'得分'"/><span>分</span></div><div class="skill-form"><label class="field">现场评价<textarea v-model="skillNote" rows="3" :disabled="skill.status==='已提交'" placeholder="记录操作过程与扣分依据…"/></label><p class="muted">操作人员：{{s.actor}} · 提交后保留操作记录</p><button class="button primary full" :disabled="skill.status==='已提交'" @click="saveSkill"><Icon name="Check" :size="17"/>{{skill.status==='已提交'?'已提交并锁定':'确认提交现场评分'}}</button></div></section></div></template>
<Empty v-if="page==='skill'&&!skill" title="暂无分配给您的技能评分任务"/><template v-if="page==='progress'"><div class="progress-dashboard"><section class="panel"><div class="panel-head"><h3>整体评阅进度</h3></div><div class="big-progress"><strong>{{Math.round(done/Math.max(1,s.visibleMarks.length)*100)}}<small>%</small></strong><div class="progress-track"><i :style="{width:done/Math.max(1,s.visibleMarks.length)*100+'%'}"></i></div><p>已核定 {{done}} / {{s.visibleMarks.length}} 份答卷</p></div></section><section class="panel"><div class="panel-head"><h3>任务状态分布</h3></div><div class="status-distribution"><div v-for="st in ['待阅卷','待另一评','待仲裁','已核定','已发布']"><Badge :text="st"/><strong>{{s.visibleMarks.filter(m=>m.status===st).length}}</strong></div></div></section></div><section class="panel spaced"><div class="panel-head"><h3>专家评分提交记录</h3></div><table><thead><tr><th>模拟评委</th><th>已提交份数</th><th>平均评分</th><th>说明</th></tr></thead><tbody><tr v-for="r in ['评委一','评委二','评委三']"><td>{{r}}</td><td>{{s.visibleMarks.filter(m=>m.scores[r]!==undefined).length}}</td><td>{{(s.visibleMarks.filter(m=>m.scores[r]!==undefined).reduce((sum,m)=>sum+m.scores[r]!,0)/Math.max(1,s.visibleMarks.filter(m=>m.scores[r]!==undefined).length)).toFixed(1)}}</td><td>从评分明细实时计算</td></tr></tbody></table></section></template>
<Modal v-if="active" :title="(active.status==='待仲裁'?'差值仲裁':'匿名答卷评阅')+' · '+active.anonymous" wide @close="active=null"><div v-if="active.revisions?.length" class="notice"><p v-for="rev in active.revisions">{{rev.time}} · {{rev.reason}} · 原评分 {{Object.entries(rev.scores).map(([r,v])=>r+' '+v).join(' / ')}} · 签名 {{rev.signature}}</p></div><div class="marking-layout"><div class="answer-document"><div class="document-label"><Icon name="FileText" :size="16"/>考生答卷 · {{active.anonymous}}</div><h3>{{active.title}}</h3><p>{{active.answer}}</p><div class="notice">客观题已判：{{active.objective}} 分<br/>主观题满分：{{active.max}} 分</div></div><div><template v-if="['已核定','已发布'].includes(active.status)"><div class="final-score"><span>核定主观成绩</span><strong>{{active.final}}<small> / {{active.max}}</small></strong></div><p v-for="(v,key) in active.scores">{{key}}：{{v}}分 · 签名 {{active.signatures?.[key]||'历史合成记录'}}</p><div class="notice">{{active.note||'依据演示规则核分'}}<br/>签名：{{active.signature}}</div></template><template v-else-if="active.status==='待仲裁'"><div class="comparison-scores"><div v-for="(v,key) in active.scores"><span>{{key}}</span><strong>{{v}}<small>分</small></strong></div></div><div v-if="active.questionIds?.length"><label v-for="(r,i) in active.rubric" class="field">{{r.label}} · 满分{{r.max}}<input v-model.number="arbitrationDetails[i]" type="number" min="0" :max="r.max" :aria-label="r.label+'仲裁分'"/></label><strong>合计 {{arbitrationDetails.reduce((a,b)=>a+b,0)}} 分</strong></div><label v-else class="field">仲裁最终分<input v-model.number="arbitrationScore" type="number" min="0" :max="active.max"/></label><label class="field">仲裁依据 <b>*</b><textarea v-model="note" rows="3" placeholder="请说明依据与定分原因"/></label></template><template v-else><div class="notice">当前阅卷人员：{{s.actor}} · {{s.person.reviewer}}</div><div class="rubric-score" v-for="(r,i) in active.rubric"><label>{{r.label}}<small>满分 {{r.max}} 分</small></label><input v-model.number="scores[i]" type="number" min="0" :max="r.max" :aria-label="r.label+'评分'"/></div><div class="scoring-total">本次合计 <strong>{{scores.reduce((a,b)=>a+Number(b),0)}} / {{active.max}}</strong></div><p class="muted">盲评模式下，本次提交前不展示另一位评委分数。</p></template><label v-if="!['已核定','已发布'].includes(active.status)" class="field">专家签名（演示文本留痕）<input v-model="signature" placeholder="请输入专家签名"/></label></div></div><template #footer><button class="button" @click="active=null">关闭</button><button v-if="active.status==='待仲裁'" class="button danger-outline" @click="s.run(()=>{p.returnReview(active!.id,note,signature);active=null})">退回重新评阅</button><button v-if="active.status==='待仲裁'" class="button primary" @click="arbitrate">确认仲裁并核定</button><button v-else-if="!['已核定','已发布'].includes(active.status)" class="button primary" @click="submit">提交本次评分</button></template></Modal>
</template>
